(6644828, 991930, 101536, '<td valign="top">You most certainly are to be congratulated for presenting us with this fabulous - very, very clever...     10!</td>', 'You most certainly are to be congratulated for presenting us with this fabulous - very, very clever...     10!', '2012-01-14 11:26:11.000000', NULL, 1),
(6644973, 991993, 142955, '<td valign="top">Classic, original and great colour theme!</td>', 'Classic, original and great colour theme!', '2012-01-14 17:33:01.000000', NULL, 1),
(6645024, 991924, 142797, '<td valign="top">well executed</td>', 'well executed', '2012-01-14 19:16:31.000000', NULL, 1),
(6645105, 991952, 94265, '<td valign="top">Lots of interesting textures, nice vibrancy on the rust. I like the angle, good focus too.</td>', 'Lots of interesting textures, nice vibrancy on the rust. I like the angle, good focus too.', '2012-01-14 21:15:06.000000', NULL, 1),
(6645108, 992131, 94265, '<td valign="top">I wouldn''t call it garbage at first glance, more like a pile of stuff waiting to be used on a worksite or something but the shot is pretty good; great tones, good exposure and focus, nice light.</td>', 'I wouldn''t call it garbage at first glance, more like a pile of stuff waiting to be used on a worksite or something but the shot is pretty good; great tones, good exposure and focus, nice light.', '2012-01-14 21:16:38.000000', NULL, 1),
(6645110, 991601, 94265, '<td valign="top">Good exposure and nice colours, clever title too.</td>', 'Good exposure and nice colours, clever title too.', '2012-01-14 21:17:04.000000', NULL, 1),
(6645119, 991717, 94265, '<td valign="top">Could do with the contrast being upped a teeny bit. I like your ''flowers''; I might have added another couple in there to fill out the can a wee bit, maybe featuring different colours to the others, like a realistic boquet. Nice clear focus.</td>', 'Could do with the contrast being upped a teeny bit. I like your ''flowers''; I might have added another couple in there to fill out the can a wee bit, maybe featuring different colours to the others, like a realistic boquet. Nice clear focus.', '2012-01-14 21:25:03.000000', NULL, 1),
(6645120, 992312, 94265, '<td valign="top">I like the reflection; the lighting stops this subject being too boring, although the highlights could stand to be up a notch. Good focus.</td>', 'I like the reflection; the lighting stops this subject being too boring, although the highlights could stand to be up a notch. Good focus.', '2012-01-14 21:26:31.000000', NULL, 1),
(6645123, 991845, 94265, '<td valign="top">Did you use coloured gels here? I quite like the colours, the mixture makes the yellow of the car pop. Nice focus too.</td>', 'Did you use coloured gels here? I quite like the colours, the mixture makes the yellow of the car pop. Nice focus too.', '2012-01-14 21:29:13.000000', NULL, 1),
(6645129, 991197, 94265, '<td valign="top">Nice dof, I like your subject and the dulled colours. The title not so much, the doll isn''t exactly bald, the hair is just solid plastic; but that''s maybe being pedantic, lol. Overall a very nice shot.</td>', 'Nice dof, I like your subject and the dulled colours. The title not so much, the doll isn''t exactly bald, the hair is just solid plastic; but that''s maybe being pedantic, lol. Overall a very nice shot.', '2012-01-14 21:44:30.000000', NULL, 1),
(6645131, 992301, 94265, '<td valign="top">Good focus, nice dof, I like the light and colours.</td>', 'Good focus, nice dof, I like the light and colours.', '2012-01-14 21:45:20.000000', NULL, 1),
(6645133, 991344, 94265, '<td valign="top">Very good focus, good dof. Nice subject and colours. I might not have included that stray petal up the top, I feel it pulls my eye from the main subject rose.</td>', 'Very good focus, good dof. Nice subject and colours. I might not have included that stray petal up the top, I feel it pulls my eye from the main subject rose.', '2012-01-14 21:49:05.000000', NULL, 1),
(6645136, 992206, 94265, '<td valign="top">These don''t look entirely like garbage, more like very poorly-stored things. Still, nice light, strong focus, good composition. A well-taken shot overall.</td>', 'These don''t look entirely like garbage, more like very poorly-stored things. Still, nice light, strong focus, good composition. A well-taken shot overall.', '2012-01-14 21:51:34.000000', NULL, 1),
(6645137, 991631, 94265, '<td valign="top">Nice different colours, enough of a mix not to be dull. Good sharp focus too. A well-taken shot.</td>', 'Nice different colours, enough of a mix not to be dull. Good sharp focus too. A well-taken shot.', '2012-01-14 21:52:41.000000', NULL, 1),
(6645138, 991994, 94265, '<td valign="top">Love the blue sky background, taken from a good angle. Almost silhouette but not quite, there are still details. Interesting bits and pieces. A good, well-composed shot.</td>', 'Love the blue sky background, taken from a good angle. Almost silhouette but not quite, there are still details. Interesting bits and pieces. A good, well-composed shot.', '2012-01-14 21:53:50.000000', NULL, 1),
(6645242, 992241, 48963, '<td valign="top">Nice creative idea and good execution!</td>', 'Nice creative idea and good execution!', '2012-01-15 03:57:08.000000', NULL, 1),
(6645243, 992201, 48963, '<td valign="top">Wow, very impressive creation, and nicely photographed.</td>', 'Wow, very impressive creation, and nicely photographed.', '2012-01-15 03:57:32.000000', NULL, 1),
(6645244, 991601, 48963, '<td valign="top">Good color and "pop", and nice choice of frame.</td>', 'Good color and "pop", and nice choice of frame.', '2012-01-15 03:58:11.000000', NULL, 1),
(6645245, 992139, 48963, '<td valign="top">Nice idea, would like to see more interesting lighting.</td>', 'Nice idea, would like to see more interesting lighting.', '2012-01-15 03:58:51.000000', NULL, 1),
(6645246, 992154, 48963, '<td valign="top">Nice idea and good execution.</td>', 'Nice idea and good execution.', '2012-01-15 03:59:18.000000', NULL, 1),
(6645247, 992237, 48963, '<td valign="top">Very cute! very nice idea and well captured.</td>', 'Very cute! very nice idea and well captured.', '2012-01-15 04:00:30.000000', NULL, 1),
(6645248, 991185, 48963, '<td valign="top">I wish the colors were a little more vivid.</td>', 'I wish the colors were a little more vivid.', '2012-01-15 04:03:14.000000', NULL, 1),
