(6645250, 992177, 48963, '<td valign="top">Nice capture, love the long exposure.</td>', 'Nice capture, love the long exposure.', '2012-01-15 04:04:07.000000', NULL, 1),
(6645251, 991483, 48963, '<td valign="top">Great title!</td>', 'Great title!', '2012-01-15 04:04:18.000000', NULL, 1),
