INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6645267, 992240, 113142, '<td valign="top">A different angle or a shift of the shapes in the frame would have contributed to the composition of this concept, and the use of a diffuser or bounce flash would have softened the light, reducing the glare of the tobacco pouch. The highlight on the pipe is nice.</td>', 'A different angle or a shift of the shapes in the frame would have contributed to the composition of this concept, and the use of a diffuser or bounce flash would have softened the light, reducing the glare of the tobacco pouch. The highlight on the pipe is nice.', '2012-01-15 05:51:29.000000', NULL, 1),
(6645319, 992141, 140537, '<td valign="top">This photo does not hold my interest for very long. It does not appear to be related to garbage.</td>', 'This photo does not hold my interest for very long. It does not appear to be related to garbage.', '2012-01-15 10:42:21.000000', NULL, 1),
(6645320, 992189, 116807, '<td valign="top">I love the composition and the colors.</td>', 'I love the composition and the colors.', '2012-01-15 10:42:44.000000', NULL, 1),
(6645321, 991694, 140537, '<td valign="top">I don''t like the soft focus. I have been looking for a photo of garbage that somehow makes me want to stay and explore the image. This does not do that.</td>', 'I don''t like the soft focus. I have been looking for a photo of garbage that somehow makes me want to stay and explore the image. This does not do that.', '2012-01-15 10:45:10.000000', NULL, 1),
(6645337, 992158, 140537, '<td valign="top">Are you suggesting that this person is garbage?</td>', 'Are you suggesting that this person is garbage?', '2012-01-15 10:58:08.000000', NULL, 1),
